import { ChangeDetectionStrategy, Component, computed, inject, input, resource, signal } from '@angular/core';
import { RouterLink } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { TranslatePipe } from '@ngx-translate/core';
import { HttpErrorResponse } from '@angular/common/http';
import { HttpClient } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { ButtonModule } from 'primeng/button';
import { TextareaModule } from 'primeng/textarea';
import { ToastService } from '@core/errors/toast.service';
import { PageHeaderComponent } from '@shared/ui/page-header/page-header.component';
import { KeyValueListComponent } from '@shared/ui/key-value-list/key-value-list.component';
import { StatusStampComponent } from '@shared/ui/status-stamp/status-stamp.component';
import { MoneyPipe } from '@shared/pipes/money.pipe';
import { DatetimePipe } from '@shared/pipes/datetime.pipe';
import { ActionResponse, ItemResponse } from '@shared/models/api.models';

interface TransferDetail {
  id: number; sender: string | null; receiver: string | null; custody_id: number | null;
  amount: string; status: string; notes: string | null; rejection_reason: string | null;
  requested_at: string | null; decided_at: string | null; decided_by: string | null;
  can_decide: boolean;
  custody?: { id: number; agent: string | null; treasury: string | null; amount: string; remaining: string; frozen: string };
}

@Component({
  selector: 'app-transfer-detail',
  standalone: true,
  imports: [TranslatePipe, RouterLink, FormsModule, ButtonModule, TextareaModule, PageHeaderComponent, KeyValueListComponent, StatusStampComponent, MoneyPipe, DatetimePipe],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (data.value(); as t) {
      <app-page-header [title]="'transfer.detail.title' | translate" [subtitle]="'#' + t.id">
        <div actions class="u-flex u-gap-2">
          @if (t.can_decide) {
            <p-button [label]="'transfer.detail.accept' | translate" size="small" (onClick)="decide(true)" [loading]="sending()" />
            <p-button [label]="'transfer.detail.reject' | translate" size="small" severity="danger" [outlined]="true" (onClick)="rejectOpen.set(true)" />
          }
          <p-button [label]="'common.back_to_list' | translate" size="small" [text]="true" routerLink="/transfers" />
        </div>
      </app-page-header>

      <div class="u-mb-4"><app-status-stamp [status]="t.status" namespace="transfer_status" [large]="true" /></div>
      @if (!t.can_decide && t.status === 'pending') {
        <p class="field__hint u-mb-4">{{ 'transfer.detail.only_receiver_hint' | translate }}</p>
      }

      <app-key-value-list [items]="keyValues(t)" />

      @if (t.custody; as c) {
        <section class="chart-card u-mt-4">
          <div class="chart-card__head"><span class="chart-card__title">{{ 'custody.detail.title' | translate }}</span></div>
          <app-key-value-list [items]="[
            { label: 'glossary.agent', value: c.agent ?? '—' },
            { label: 'glossary.treasury', value: c.treasury ?? '—' },
            { label: 'common.amount', value: c.amount | money },
            { label: 'transfer.create.available', value: c.remaining | money },
            { label: 'dashboard.agent.frozen', value: c.frozen | money }
          ]" />
        </section>
      }

      @if (rejectOpen()) {
        <section class="form-section u-mt-4">
          <h3 class="form-section__title">{{ 'transfer.detail.confirm_reject' | translate }}</h3>
          <div class="field">
            <label class="field__label" for="reason">{{ 'transfer.detail.reject_reason' | translate }} *</label>
            <textarea pTextarea id="reason" rows="2" [(ngModel)]="rejectReason" name="rejectReason" style="width: 100%"></textarea>
          </div>
          <div class="u-flex" style="justify-content: flex-end">
            <p-button [label]="'common.cancel' | translate" [text]="true" (onClick)="rejectOpen.set(false)" />
            <p-button [label]="'transfer.detail.confirm_reject' | translate" severity="danger" (onClick)="decide(false)" [loading]="sending()" />
          </div>
        </section>
      }
    }
  `,
})
export class TransferDetailPage {
  private http = inject(HttpClient);
  private toast = inject(ToastService);

  id = input.required<number>();
  sending = signal(false);
  rejectOpen = signal(false);
  rejectReason = signal('');

  data = resource<TransferDetail, { id: number }>({
    params: () => ({ id: this.id() }),
    loader: ({ params }) =>
      firstValueFrom(this.http.get<ItemResponse<TransferDetail>>(`/custody-transfers/${params.id}`)).then((res) => res.data),
  });

  keyValues(t: TransferDetail): { label: string; value: string }[] {
    return [
      { label: 'glossary.sender', value: t.sender ?? '—' },
      { label: 'glossary.receiver', value: t.receiver ?? '—' },
      { label: 'common.amount', value: t.amount },
      { label: 'transfer.list.col_custody', value: t.custody_id ? '#' + t.custody_id : '—' },
      { label: 'common.notes', value: t.notes ?? '—' },
      { label: 'transfer.list.col_requested_at', value: t.requested_at ?? '—' },
      { label: 'transfer.list.col_decided_at', value: t.decided_at ?? '—' },
      { label: 'transfer.list.col_decided_by', value: t.decided_by ?? '—' },
      { label: 'transfer.list.col_rejection', value: t.rejection_reason ?? '—' },
    ];
  }

  decide(accept: boolean): void {
    this.sending.set(true);
    const path = accept ? 'approve' : 'reject';
    void firstValueFrom(
      this.http.post<ActionResponse>(`/custody-transfers/${this.id()}/${path}`, {
        ...(accept ? { custody_id: this.data.value()?.custody_id } : { reason: this.rejectReason() }),
      }),
    ).then((res) => {
      this.sending.set(false);
      this.toast.success(res.message);
      this.data.reload();
    }).catch((err: HttpErrorResponse) => {
      this.sending.set(false);
      this.toast.apiError(err.error?.message ?? '', err.error?.code);
    });
  }
}
